import { apiFetch } from '@/lib/api/client';

/**
 * The QR codes people scan at a property.
 *
 * A code is a stable id plus the address it forwards to, so a printed sign never
 * has to be replaced: change the destination here and every copy of the code
 * points somewhere new. The picture is generated by the API from the id, so the
 * drawing and the public page can never disagree.
 *
 * A code can also ask for support to be told when it is scanned: who, what the
 * message says, and whether it should be loud or quiet.
 */

/** `loud` should interrupt; `quiet` should arrive silently. */
export type QrNotificationPriority = 'loud' | 'quiet';

export interface QrNotification {
  title: string;
  body: string;
  priority: QrNotificationPriority;
}

export interface QrCode {
  id: string;
  name: string;
  url: string;
  active: boolean;
  createdAt: string | null;
  /** Where the code resolves, and the kiosk page that displays it. */
  links: { code: string; kiosk: string };
  /**
   * The property this sign stands at.
   *
   * An alert is only useful if it says where: "someone scanned a code" is a
   * puzzle, "someone is at Maple Street" is a job.
   */
  locationId: string | null;
  /**
   * The video kiosk beside this sign.
   *
   * Answering an alert from this code can start a call on that device, which is
   * what pairing them is for — whoever scanned is standing in front of it.
   */
  rtcDeviceId: string | null;
  /** The notification tags told on each scan. These are the audience and the switch. */
  notifyTags: string[];
  /** Named accounts, kept for codes set up before tags existed. */
  notifyUserIds: string[];
  notification: QrNotification;
}

export interface QrCodePatch {
  name?: string;
  url?: string;
  active?: boolean;
  /** An id, or null to clear it. */
  locationId?: string | null;
  rtcDeviceId?: string | null;
  /** The audience. Choosing tags is what makes a code notify. */
  notifyTags?: string[];
  notifyUserIds?: string[];
  /** Merged over what is stored, so a partial save stays partial. */
  notification?: Partial<QrNotification>;
}

export async function listQrCodes(includeInactive = false): Promise<QrCode[]> {
  const { codes } = await apiFetch<{ codes: QrCode[] }>(
    `/api/mobile/admin/qr-codes${includeInactive ? '?includeInactive=1' : ''}`,
  );
  return codes;
}

export async function createQrCode(name: string, url: string): Promise<QrCode> {
  const { code } = await apiFetch<{ code: QrCode }>('/api/mobile/admin/qr-codes', {
    method: 'POST',
    body: { name, url },
  });
  return code;
}

export async function updateQrCode(codeId: string, patch: QrCodePatch): Promise<QrCode> {
  const { code } = await apiFetch<{ code: QrCode }>(
    `/api/mobile/admin/qr-codes/${encodeURIComponent(codeId)}`,
    { method: 'PATCH', body: patch },
  );
  return code;
}

/**
 * The code as SVG markup, drawn by react-native-svg.
 *
 * A native image source cannot carry the bearer token, so the drawing comes back
 * as text and the app renders it; the same endpoint is what the site prints.
 */
export async function qrCodeSvg(codeId: string): Promise<string> {
  const { svg } = await apiFetch<{ svg: string }>(
    `/api/mobile/admin/qr-codes/${encodeURIComponent(codeId)}/svg`,
  );
  return svg;
}
